class Solution:
    def maximumSegmentSum(self, nums, removeQueries):
        n = len(nums)
        removed = [False] * n
        ans = []
        for q in removeQueries:
            removed[q] = True
            best = cur = 0
            for i in range(n):
                if removed[i]:
                    cur = 0
                else:
                    cur += nums[i]
                    best = max(best, cur)
            ans.append(best)
        return ans

