        n = len(nums)
        par = list(range(n)); sz = [0] * n
        active = [False] * n
        best = 0; ans = []
        def find(x):
            while par[x] != x:
                par[x] = par[par[x]]; x = par[x]
            return x
        for q in reversed(removeQueries):
            ans.append(best)
            active[q] = True; sz[q] = nums[q]
            for nb in (q - 1, q + 1):
                if 0 <= nb < n and active[nb]:
                    r = find(nb); sz[q] += sz[r]; par[r] = q
            best = max(best, sz[q])
        return ans[::-1]

