class Solution {
    vector<int> par; vector<long long> sz;
    int find(int x){ while(par[x]!=x){par[x]=par[par[x]];x=par[x];} return x; }
public:
    vector<long long> maximumSegmentSum(vector<int>& nums, vector<int>& removeQueries) {
        int n = nums.size();
        par.resize(n); sz.assign(n, 0);
        vector<char> active(n, false);
        long long best = 0; vector<long long> ans;
        for (int i = n - 1; i >= 0; i--) {
            int q = removeQueries[i];
            ans.push_back(best);
            active[q] = true; sz[q] = nums[q];
            for (int nb : {q-1, q+1})
                if (nb >= 0 && nb < n && active[nb]) {
                    int r = find(nb); sz[q] += sz[r]; par[r] = q;
                }
            best = max(best, sz[q]);
        }
        reverse(ans.begin(), ans.end());
        return ans;
    }
};

