class Solution {
    int[] par; long[] sz;
    int find(int x){ while(par[x]!=x){par[x]=par[par[x]];x=par[x];} return x; }
    public long[] maximumSegmentSum(int[] nums, int[] removeQueries) {
        int n = nums.length;
        par = new int[n]; sz = new long[n];
        boolean[] active = new boolean[n];
        long best = 0; long[] ans = new long[n];
        for (int i = n - 1; i >= 0; i--) {
            int q = removeQueries[i];
            ans[i] = best;
            active[q] = true; sz[q] = nums[q];
            for (int nb : new int[]{q-1, q+1})
                if (nb >= 0 && nb < n && active[nb]) {
                    int r = find(nb); sz[q] += sz[r]; par[r] = q;
                }
            best = Math.max(best, sz[q]);
        }
        for (int i = 0; i < n / 2; i++) { long t = ans[i]; ans[i] = ans[n-1-i]; ans[n-1-i] = t; }
        return ans;
    }
}

