    const par = [...Array(n).keys()], sz = Array(n).fill(0), active = Array(n).fill(false);
    const find = x => { while (par[x] !== x) { par[x] = par[par[x]]; x = par[x]; } return x; };
    let best = 0; const ans = [];
    for (let i = n - 1; i >= 0; i--) {
        const q = removeQueries[i];
        ans.push(best);
        active[q] = true; sz[q] = nums[q];
        for (const nb of [q - 1, q + 1])
            if (nb >= 0 && nb < n && active[nb]) {
                const r = find(nb); sz[q] += sz[r]; par[r] = q;
            }
        best = Math.max(best, sz[q]);
    }
